const BLYNK_BASE = "http://167.71.221.155:8080";
const BLYNK_TOKEN = "Replace-Your-Blynk-Token-Here";

const pins = [
  {
    key: "valve1",
    virtual_pin: "V1",
    label: "Valve 1",
    unit: ""
  },
  {
    key: "soil",
    virtual_pin: "V2",
    label: "Soil Moisture",
    unit: "%"
  },
  {
    key: "auto_mode",
    virtual_pin: "V3",
    label: "Auto Manual Mode",
    unit: ""
  },
  {
    key: "slider_threshold",
    virtual_pin: "V4",
    label: "Soil Moisture Slider Threshold",
    unit: "%"
  }
];

return pins.map(pin => {
  return {
    json: {
      ...pin,
      url: `${BLYNK_BASE}/${BLYNK_TOKEN}/get/${pin.virtual_pin}`
    }
  };
});

function extractBlynkValue(input) {
  let rawValue;

  if (typeof input === "string") {
    rawValue = input;
  } 
  else if (typeof input === "number") {
    rawValue = input;
  }
  else if (Array.isArray(input)) {
    rawValue = input[0];
  } 
  else if (typeof input.body === "string") {
    rawValue = input.body;
  } 
  else if (Array.isArray(input.body)) {
    rawValue = input.body[0];
  } 
  else if (typeof input.data === "string") {
    rawValue = input.data;
  } 
  else if (Array.isArray(input.data)) {
    rawValue = input.data[0];
  }
  else {
    const values = Object.values(input);

    if (values.every(v => typeof v === "string" && v.length === 1)) {
      rawValue = values.join("");
    } else {
      rawValue = values[0];
    }
  }

  return rawValue;
}

function toBool(value) {
  return ["1", "true", "on", "auto", "AUTO"].includes(String(value).trim());
}

// ===============================
// 1) ดึงข้อมูลจาก Blynk V1-V4
// ===============================
const pinItems = $("Prepare Blynk Pin List").all();
const responseItems = $input.all();

const raw = {};

for (let i = 0; i < responseItems.length; i++) {
  const key = pinItems[i].json.key;
  const response = responseItems[i].json;
  raw[key] = extractBlynkValue(response);
}

// ===============================
// 2) แปลงค่าข้อมูล
// ===============================
const valve1 = toBool(raw.valve1);
const valve1Status = valve1 ? "ON" : "OFF";

const autoMode = toBool(raw.auto_mode);
const autoModeText = autoMode ? "Auto" : "Manual";

const soilRaw = Number(raw.soil);
const thresholdRaw = Number(raw.slider_threshold);

const soilMoisture = Number.isFinite(soilRaw)
  ? Number(soilRaw.toFixed(1))
  : null;

const sliderThreshold = Number.isFinite(thresholdRaw)
  ? Number(thresholdRaw.toFixed(1))
  : null;

// ===============================
// 3) ตั้งค่า Alert Policy
// ===============================
const cooldownMinutes = 15;   // เปลี่ยนเป็น 30 ได้ถ้าต้องการแจ้งซ้ำทุก 30 นาที
const hysteresis = 1.0;       // ค่ากลับสู่ปกติต้อง >= Slider + 1.0 เพื่อกันแจ้งเตือนสลับไปมา

const now = new Date();
const nowMs = Date.now();

const thaiTime = now.toLocaleString("th-TH", {
  timeZone: "Asia/Bangkok",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit"
});

const siteId = "site01";
const deviceId = "esp32_smartfarm_01";
const slaveId = 1;

// ใช้จำสถานะข้ามรอบการทำงานของ Workflow
const staticData = $getWorkflowStaticData("global");
const alertKey = `${siteId}_${deviceId}_soil_slave_${slaveId}`;

const lastAlertAt = staticData[`lastAlertAt_${alertKey}`] || 0;
const wasInAlert = staticData[`wasInAlert_${alertKey}`] || false;

// ===============================
// 4) ตรวจสอบเงื่อนไข
// ===============================
const isLowSoil =
  autoMode === true &&
  soilMoisture !== null &&
  sliderThreshold !== null &&
  soilMoisture < sliderThreshold;

const isRecovered =
  autoMode === true &&
  wasInAlert === true &&
  soilMoisture !== null &&
  sliderThreshold !== null &&
  soilMoisture >= sliderThreshold + hysteresis;

let shouldSendLine = false;
let eventStatus = "normal";
let lineMessage = "";

// ===============================
// 5) กรณีความชื้นต่ำ
// ===============================
if (isLowSoil) {
  const cooldownPassed =
    !lastAlertAt || (nowMs - lastAlertAt) >= cooldownMinutes * 60 * 1000;

  if (!wasInAlert) {
    // แจ้งเตือนครั้งแรกทันที
    shouldSendLine = true;
    eventStatus = "low_soil_moisture_first_alert";

    staticData[`lastAlertAt_${alertKey}`] = nowMs;
    staticData[`wasInAlert_${alertKey}`] = true;
  } 
  else if (cooldownPassed) {
    // แจ้งซ้ำเมื่อยังต่ำอยู่ และครบเวลา Cooldown แล้ว
    shouldSendLine = true;
    eventStatus = "low_soil_moisture_repeat_alert";

    staticData[`lastAlertAt_${alertKey}`] = nowMs;
    staticData[`wasInAlert_${alertKey}`] = true;
  } 
  else {
    // ยังต่ำอยู่ แต่ยังไม่ครบเวลาแจ้งซ้ำ
    shouldSendLine = false;
    eventStatus = "low_soil_moisture_waiting_cooldown";

    staticData[`wasInAlert_${alertKey}`] = true;
  }

  if (shouldSendLine) {
    lineMessage =
`⚠️ แจ้งเตือนความชื้นในดินต่ำ

พื้นที่: ${siteId}
อุปกรณ์: ${deviceId}
เซนเซอร์: Soil Moisture Slave ID ${slaveId}

ค่าความชื้นปัจจุบัน: ${soilMoisture.toFixed(1)} %
ค่าที่ตั้งไว้บน Slider: ${sliderThreshold.toFixed(1)} %

สถานะโหมด: ${autoModeText}
สถานะวาล์ว 1: ${valve1Status}

คำแนะนำ: ค่าความชื้นต่ำกว่าที่กำหนดไว้ ควรตรวจสอบการทำงานของวาล์วหรือระบบให้น้ำ

เวลา: ${thaiTime}`;
  }
}

// ===============================
// 6) กรณีค่ากลับมาปกติ
// ===============================
else if (isRecovered) {
  shouldSendLine = true;
  eventStatus = "recovered";

  staticData[`wasInAlert_${alertKey}`] = false;
  staticData[`lastAlertAt_${alertKey}`] = 0;

  lineMessage =
`✅ ความชื้นในดินกลับสู่ระดับปกติ

พื้นที่: ${siteId}
อุปกรณ์: ${deviceId}
เซนเซอร์: Soil Moisture Slave ID ${slaveId}

ค่าความชื้นปัจจุบัน: ${soilMoisture.toFixed(1)} %
ค่าที่ตั้งไว้บน Slider: ${sliderThreshold.toFixed(1)} %

สถานะโหมด: ${autoModeText}
สถานะวาล์ว 1: ${valve1Status}

สถานะ: ค่าความชื้นกลับเข้าสู่ระดับปกติแล้ว

เวลา: ${thaiTime}`;
}

// ===============================
// 7) กรณีปกติ
// ===============================
else {
  shouldSendLine = false;

  if (!autoMode) {
    eventStatus = "manual_mode";
  } else {
    eventStatus = "normal";
  }

  // ถ้า Auto Mode เปิดอยู่ และค่าอยู่ในเกณฑ์ปกติ ให้ reset alert state
  if (autoMode && soilMoisture !== null && sliderThreshold !== null && soilMoisture >= sliderThreshold + hysteresis) {
    staticData[`wasInAlert_${alertKey}`] = false;
    staticData[`lastAlertAt_${alertKey}`] = 0;
  }
}

// ===============================
// 8) ส่งออกข้อมูล
// ===============================
return [
  {
    json: {
      site_id: siteId,
      device_id: deviceId,

      sensor_type: "soil_moisture",
      sensor_name: "soil_moisture_slave_1",
      modbus_slave_id: slaveId,
      slave_id: slaveId,

      valve1: valve1,
      valve1_raw: raw.valve1,
      valve1_status: valve1Status,
      valve1_virtual_pin: "V1",

      soil_moisture: soilMoisture,
      soil_moisture_display: soilMoisture !== null ? soilMoisture.toFixed(1) + " %" : null,
      soil_virtual_pin: "V2",

      auto_mode: autoMode,
      auto_mode_text: autoModeText,
      auto_mode_raw: raw.auto_mode,
      auto_mode_virtual_pin: "V3",

      slider_threshold: sliderThreshold,
      slider_threshold_display: sliderThreshold !== null ? sliderThreshold.toFixed(1) + " %" : null,
      slider_virtual_pin: "V4",

      unit: "%",

      should_send_line: shouldSendLine,
      event_status: eventStatus,
      cooldown_minutes: cooldownMinutes,
      hysteresis: hysteresis,

      line_message: lineMessage,

      timestamp: now.toISOString(),
      timestamp_th: thaiTime,

      raw_blynk_values: raw
    }
  }
];

const data = $json;

function escapeTag(value) {
  return String(value ?? "")
    .replace(/ /g, "\\ ")
    .replace(/,/g, "\\,")
    .replace(/=/g, "\\=");
}

function toNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

const measurement = "smartfarm_soil";

const siteId = escapeTag(data.site_id || "site01");
const deviceId = escapeTag(data.device_id || "esp32_smartfarm_01");
const sensorName = escapeTag(data.sensor_name || "soil_moisture_slave_1");
const slaveId = escapeTag(data.slave_id || 1);

const soilMoisture = toNumber(data.soil_moisture);
const sliderThreshold = toNumber(data.slider_threshold);

const valve1Value = data.valve1 === true ? 1 : 0;
const autoModeValue = data.auto_mode === true ? 1 : 0;
const shouldSendLineValue = data.should_send_line === true ? 1 : 0;

// ใช้ timestamp เป็นวินาที เพราะ HTTP Request จะกำหนด precision=s
const timestamp = Math.floor(Date.now() / 1000);

const lineProtocol =
`${measurement},site_id=${siteId},device_id=${deviceId},sensor_name=${sensorName},slave_id=${slaveId} ` +
`soil_moisture=${soilMoisture},slider_threshold=${sliderThreshold},valve1=${valve1Value},auto_mode=${autoModeValue},should_send_line=${shouldSendLineValue} ${timestamp}`;

return [
  {
    json: {
      ...data,
      influx_line: lineProtocol
    }
  }
];
